package main

import (
	"fmt"
	"os"
	"reflect"

	"alphametics"
)

func main() {
	checks := []struct {
		name    string
		puzzle  string
		want    map[string]int
		wantErr bool
	}{
		{name: "send-more", puzzle: "SEND + MORE == MONEY", want: map[string]int{"D": 7, "E": 5, "M": 1, "N": 6, "O": 0, "R": 8, "S": 9, "Y": 2}},
		{name: "three-letters", puzzle: "I + BB == ILL", want: map[string]int{"B": 9, "I": 1, "L": 0}},
		{name: "single-identity", puzzle: "A == A", want: map[string]int{"A": 0}},
		{name: "unique-values", puzzle: "A == B", wantErr: true},
		{name: "leading-zero", puzzle: "ACA + DD == BD", wantErr: true},
		{name: "missing-equals", puzzle: "A + B = C", wantErr: true},
		{name: "digit-in-puzzle", puzzle: "A + 1 == B", wantErr: true},
	}

	ok := true
	for _, check := range checks {
		got, err := alphametics.Solve(check.puzzle)
		if check.wantErr {
			if err == nil {
				fmt.Printf("FAIL %s: expected error, got %#v\n", check.name, got)
				ok = false
			} else {
				fmt.Printf("PASS %s: expected error\n", check.name)
			}
			continue
		}
		if err != nil {
			fmt.Printf("FAIL %s: unexpected error: %v\n", check.name, err)
			ok = false
			continue
		}
		if !reflect.DeepEqual(got, check.want) {
			fmt.Printf("FAIL %s: got %#v, want %#v\n", check.name, got, check.want)
			ok = false
			continue
		}
		fmt.Printf("PASS %s\n", check.name)
	}
	if !ok {
		os.Exit(1)
	}
}
